<section class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1>Course catalogue</h1><p class="text-muted">Find your next course.</p></div><form class="d-flex" method="get"><input class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search courses"><button class="btn btn-primary ms-2">Search</button></form></div><div class="row g-4"><?php if (!$courses): ?><div class="col-12"><div class="alert alert-info">No matching courses found.</div></div><?php endif; ?><?php foreach ($courses as $course): ?><div class="col-md-4"><div class="card h-100"><div class="card-body"><h2 class="h5"><?= e($course['title']) ?></h2><p class="small text-muted">By <?= e($course['instructor']) ?></p><p><?= e(substr((string)$course['description'], 0, 140)) ?></p><a class="btn btn-outline-primary" href="/course?slug=<?= urlencode($course['slug']) ?>">View course</a></div></div></div><?php endforeach; ?></div></section>